-- C85: D-A72 är en skenmonterad givare, inte bandmonterad.
--
-- Katalogens givartabell (sida 6) har A72 i kolumnen "Rail mounting,
-- Perpendicular" och A72H i "Rail mounting, In-line"; bandkolumnerna är
-- tomma för 200 V-reeden. Modellen hade A72 som bandtyp — rättat i
-- src/lib/catalog/c85.ts. Regelparet band/skena, etiketterna och
-- schema_json är regenererade ur den rättade modellen.
--
-- Lades på databasen 2026-09-15 via apply_migration i tre delar:
--   c85_a72_is_rail_type_part_01  (etiketter, delete, regler 1–20)
--   c85_a72_is_rail_type_part_02  (regler 21–40, oförändrade)
--   c85_a72_is_rail_type_part_03  (schema_json)
-- Fingeravtryck efter körning, identiska med modellen:
--   regler  40   md5 c849a88020ffd2cd9457a599992d46f0   villkor d92faba9f60685fd991dd100201098a7
--   värden  70   md5 0edbadc843f1c8a7f66ced5c15309dc1
--   schema       md5 28d10e872f44e24cf766e4859232f27b

begin;

-- etiketter
update configurator_param_values v set label = 'D-A72, reed 200 V, vinklad (skena)' from configurator_params p, configurator_families f where v.param_id = p.id and p.family_id = f.id and f.slug = 'c85' and p.param_key = 'switch' and v.code = 'A72';

update configurator_param_values v set label = 'D-A72H, reed 200 V, rak (skena)' from configurator_params p, configurator_families f where v.param_id = p.id and p.family_id = f.id and f.slug = 'c85' and p.param_key = 'switch' and v.code = 'A72H';

delete from config_rules where schema_id = 'SCHEMA-C85-V1';

insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-C85-V1', r->>'severity', r->'if_json',
       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"error","if_json":{"and":[{"==":[{"var":"cushion"},"C"]},{"in":[{"var":"bore"},["8"]]}]},"message_sv":"Luftdämpning finns inte för ø8 (sida 6).","message_en":"Air cushion is not available for ø8 (page 6).","goto_step":"c85-cushion"},{"severity":"error","if_json":{"and":[{"==":[{"var":"cushion"},"C"]},{"in":[{"var":"cover"},["E","F","Y"]]}]},"message_sv":"Luftdämpning finns bara med basgaveln N, inte E, F och Y (sida 6).","message_en":"Air cushion exists only with the basic head cover N, not E, F and Y (page 6).","goto_step":"c85-cushion"},{"severity":"error","if_json":{"and":[{"==":[{"var":"cushion"},"C"]},{">":[{"var":"stroke_mm"},0]},{"<":[{"var":"stroke_mm"},25]}]},"message_sv":"Med luftdämpning är minsta slag 25 mm (sida 7, not 4).","message_en":"With air cushion the minimum stroke is 25 mm (page 7, note 4).","goto_step":"c85-stroke_mm"},{"severity":"error","if_json":{"and":[{"in":[{"var":"boot"},["J","K"]]},{"in":[{"var":"bore"},["8","10","12","16"]]}]},"message_sv":"Bälg finns bara för ø20 och 25.","message_en":"The rod boot exists only for ø20 and 25.","goto_step":"c85-boot"},{"severity":"error","if_json":{"and":[{"==":[{"var":"cover"},"E"]},{"in":[{"var":"bracket"},["N"]]}]},"message_sv":"Gavel E tar fäste L, M, G eller U, inte N (sida 6).","message_en":"Head cover E takes bracket L, M, G or U, not N (page 6).","goto_step":"c85-bracket"},{"severity":"error","if_json":{"and":[{"==":[{"var":"cover"},"F"]},{"in":[{"var":"bracket"},["M","N"]]}]},"message_sv":"Gavel F tar fäste L, G eller U, inte M och N (sida 6).","message_en":"Head cover F takes bracket L, G or U, not M and N (page 6).","goto_step":"c85-bracket"},{"severity":"error","if_json":{"and":[{"==":[{"var":"cover"},"Y"]},{"in":[{"var":"bracket"},["M","N"]]}]},"message_sv":"Gavel Y tar fäste L, G eller U, inte M och N (sida 6).","message_en":"Head cover Y takes bracket L, G or U, not M and N (page 6).","goto_step":"c85-bracket"},{"severity":"error","if_json":{"and":[{"!=":[{"var":"switch_mount"},""]},{"!=":[{"var":"magnet"},"D"]}]},"message_sv":"Givarfästet (A/B) anges bara för magnetcylindern CD85 — välj inbyggd magnet, eller inget fäste.","message_en":"The auto switch mounting type (A/B) is specified only for the CD85 magnet cylinder — choose the built-in magnet, or no mounting type.","goto_step":"c85-switch_mount"},{"severity":"error","if_json":{"and":[{"==":[{"var":"magnet"},"D"]},{">":[{"var":"stroke_mm"},0]},{"==":[{"var":"switch_mount"},""]}]},"message_sv":"Magnetcylindern CD85 beställs med givarfäste: A för skena eller B för band (sida 6).","message_en":"The CD85 magnet cylinder is ordered with an auto switch mounting type: A for rail or B for band (page 6).","goto_step":"c85-switch_mount"},{"severity":"error","if_json":{"and":[{"!=":[{"var":"switch"},""]},{"==":[{"var":"switch_mount"},""]}]},"message_sv":"En givare kräver magnetcylindern CD85 med givarfäste A eller B.","message_en":"An auto switch needs the CD85 magnet cylinder with mounting type A or B.","goto_step":"c85-switch_mount"},{"severity":"error","if_json":{"and":[{"==":[{"var":"switch_mount"},"A"]},{"in":[{"var":"switch"},["H7C","H7NF","C73C","C80C"]]}]},"message_sv":"D-H7C, H7NF, C73C och C80C finns bara för bandmontage (B).","message_en":"D-H7C, H7NF, C73C and C80C exist for band mounting (B) only.","goto_step":"c85-switch"},{"severity":"error","if_json":{"and":[{"==":[{"var":"switch_mount"},"B"]},{"in":[{"var":"switch"},["J79C","F79F","A72","A72H","A73C","A80C","A79W"]]}]},"message_sv":"D-J79C, F79F, A72, A72H, A73C, A80C och A79W finns bara för skenmontage (A).","message_en":"D-J79C, F79F, A72, A72H, A73C, A80C and A79W exist for rail mounting (A) only.","goto_step":"c85-switch"},{"severity":"error","if_json":{"and":[{"==":[{"var":"switch_mount"},"B"]},{"in":[{"var":"switch"},["A96","A96V","A93","A93V","A90","A90V"]]},{"in":[{"var":"bore"},["8","10","12"]]}]},"message_sv":"D-A96/A96V/A93/A93V/A90/A90V kan inte monteras med band på ø8, 10 och 12 (sida 6).","message_en":"D-A96/A96V/A93/A93V/A90/A90V cannot be band-mounted on ø8, 10 and 12 (page 6).","goto_step":"c85-switch"},{"severity":"error","if_json":{"and":[{"==":[{"var":"switch_mount"},"A"]},{"in":[{"var":"switch"},["M9N","M9P","M9B","M9NV","M9PV","M9BV","M9NW","M9PW","M9BW","M9NWV","M9PWV","M9BWV","M9NA","M9PA","M9BA","M9NAV","M9PAV","M9BAV"]]},{"in":[{"var":"bore"},["20","25"]]}]},"message_sv":"D-M9N/M9P/M9B/M9NV/M9PV/M9BV/M9NW/M9PW/M9BW/M9NWV/M9PWV/M9BWV/M9NA/M9PA/M9BA/M9NAV/M9PAV/M9BAV kan inte monteras på skena på ø20 och 25 (sida 6).","message_en":"D-M9N/M9P/M9B/M9NV/M9PV/M9BV/M9NW/M9PW/M9BW/M9NWV/M9PWV/M9BWV/M9NA/M9PA/M9BA/M9NAV/M9PAV/M9BAV cannot be rail-mounted on ø20 and 25 (page 6).","goto_step":"c85-switch"},{"severity":"error","if_json":{"and":[{"==":[{"var":"switch_mount"},"A"]},{"in":[{"var":"switch"},["A96","A96V","A93","A93V","A90","A90V","A79W"]]},{"in":[{"var":"bore"},["8","10","12"]]}]},"message_sv":"D-A96/A96V/A93/A93V/A90/A90V/A79W kan inte monteras på skena på ø8, 10 och 12 (sida 6).","message_en":"D-A96/A96V/A93/A93V/A90/A90V/A79W cannot be rail-mounted on ø8, 10 and 12 (page 6).","goto_step":"c85-switch"},{"severity":"error","if_json":{"and":[{"==":[{"var":"switch"},""]},{"or":[{"!=":[{"var":"lead"},""]},{"!=":[{"var":"count"},""]}]}]},"message_sv":"Kabellängd och antal hör till givaren — välj en givare först.","message_en":"Lead wire length and quantity belong to the auto switch — choose a switch first.","goto_step":"c85-switch"},{"severity":"error","if_json":{"and":[{"in":[{"var":"bore"},["8","10"]]},{">":[{"var":"stroke_mm"},200]},{"!=":[{"var":"mto"},"X2018"]}]},"message_sv":"ø8 och 10 går till 200 mm slag; längre beställs som special -X2018 (sida 7, not 3).","message_en":"ø8 and 10 goes up to 200 mm stroke; longer is a special order -X2018 (page 7, note 3).","goto_step":"c85-stroke_mm"},{"severity":"error","if_json":{"and":[{"in":[{"var":"bore"},["8","10"]]},{">":[{"var":"stroke_mm"},0]},{"<=":[{"var":"stroke_mm"},200]},{"==":[{"var":"mto"},"X2018"]}]},"message_sv":"-X2018 är för slag över 200 mm; ø8 och 10 har det slaget som standard.","message_en":"-X2018 is for strokes above 200 mm; ø8 and 10 has that stroke as standard.","goto_step":"c85-mto"},{"severity":"error","if_json":{"and":[{"in":[{"var":"bore"},["12","16"]]},{">":[{"var":"stroke_mm"},400]},{"!=":[{"var":"mto"},"X2018"]}]},"message_sv":"ø12 och 16 går till 400 mm slag; längre beställs som special -X2018 (sida 7, not 3).","message_en":"ø12 and 16 goes up to 400 mm stroke; longer is a special order -X2018 (page 7, note 3).","goto_step":"c85-stroke_mm"},{"severity":"error","if_json":{"and":[{"in":[{"var":"bore"},["12","16"]]},{">":[{"var":"stroke_mm"},0]},{"<=":[{"var":"stroke_mm"},400]},{"==":[{"var":"mto"},"X2018"]}]},"message_sv":"-X2018 är för slag över 400 mm; ø12 och 16 har det slaget som standard.","message_en":"-X2018 is for strokes above 400 mm; ø12 and 16 has that stroke as standard.","goto_step":"c85-mto"}]'::jsonb) r;

